import{_ as i,o,c as a,ai as t}from"./chunks/framework.lvpqbiZd.js";const u=JSON.parse('{"title":"Asumi Hero and Design System Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-31-asumi-hero-design.md","filePath":"superpowers/specs/2026-08-31-asumi-hero-design.md"}'),r={name:"superpowers/specs/2026-08-31-asumi-hero-design.md"};function s(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="asumi-hero-and-design-system-design" tabindex="-1">Asumi Hero and Design System Design <a class="header-anchor" href="#asumi-hero-and-design-system-design" aria-label="Permalink to “Asumi Hero and Design System Design”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Replace the public root of <code>asumi.ir</code> with a responsive React hero that expresses the Asumi brand story: darkness becomes light, and light represents a bright future. This phase creates only the hero and its reusable design-system foundation. Product pages and CTA destinations are explicitly out of scope.</p><h2 id="brand-direction" tabindex="-1">Brand Direction <a class="header-anchor" href="#brand-direction" aria-label="Permalink to “Brand Direction”">​</a></h2><ul><li>Brand: <code>ASUMI</code> / <code>明日美</code></li><li>English line: <code>A Beautiful Tomorrow</code></li><li>Persian line: <code>آینده ای روشن</code></li><li>Motion story: <code>Darkness -&gt; Light -&gt; Clarity -&gt; Future</code></li><li>Dark theme name: <code>Midnight Horizon</code></li><li>Light theme name: <code>Morning Horizon</code></li><li>Accent: copper-gold light, never neon or purple.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><ul><li>Create a separate <code>React + TypeScript + Vite</code> public frontend for <code>asumi.ir</code>.</li><li>Route only the public root through the Asumi app; preserve native Frappe routes such as <code>/desk</code>, <code>/dashboard</code>, <code>/api</code>, <code>/assets</code>, <code>/files</code>, and <code>/app</code>.</li><li>Implement dark and light themes, including a cinematic theme transition.</li><li>Build the Hero from reusable atoms, molecules, and one Hero organism.</li><li>Use SVG, CSS, and GSAP for all visual motion. Do not introduce Three.js or React Three Fiber in this phase.</li><li>The CTA is visible and interactive but does not navigate until the products section exists.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of Scope”">​</a></h2><ul><li>Product grid, pricing, customer portal, forms, analytics, and backend APIs.</li><li>Any change to Press administration, client sites, or customer databases.</li><li>WebGL, video backgrounds, and custom desktop cursors.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p>The new app lives in <code>dashboard/asumi</code>. Vite emits static assets to <code>press/public/asumi_site</code> and a Frappe-rendered HTML shell to <code>press/www/asumi.html</code>. The existing Press path resolver will receive a small Asumi-only host mapping for the root route. It must defer all reserved routes to Frappe&#39;s default resolver.</p><p>The frontend is organized by visual responsibility:</p><ul><li><code>styles/tokens.css</code>: colors, typography, spacing, radius, borders, light, and motion-duration variables for both themes.</li><li><code>components/atoms</code>: primitive visual components such as the brand mark, icon button, CTA button, and particle.</li><li><code>components/molecules</code>: theme switcher, brand lockup, and orbit composition.</li><li><code>components/organisms</code>: the complete Hero timeline and scene composition.</li><li><code>hooks</code>: motion preference, pointer parallax, and theme state behavior.</li></ul><h2 id="hero-scene" tabindex="-1">Hero Scene <a class="header-anchor" href="#hero-scene" aria-label="Permalink to “Hero Scene”">​</a></h2><p>The Hero occupies <code>100svh</code> and starts visually black (<code>#080A0B</code>). It uses an inline SVG scene composed of a horizon, reflective light, three orbit rings, three layered translucent light waves, and a small deterministic particle set. No raster image is required.</p><p>The initial animation is interruptible: the page remains scrollable immediately and a reduced-motion visitor sees the final scene after a short fade. The normal timeline completes in approximately three seconds:</p><ol><li>A small horizon glow appears at the bottom center.</li><li>The glow expands into a sunrise and a blurred reflection.</li><li>The orbit rings draw with <code>stroke-dashoffset</code>, then drift slowly in opposing directions.</li><li>Light waves fade and slide into place.</li><li><code>ASUMI</code> resolves from wide tracking and blur.</li><li><code>明日美</code>, the English line, and Persian line reveal in sequence; the Persian word <code>روشن</code> coincides with a subtle horizon pulse.</li><li>Particles begin low-amplitude ambient movement.</li><li>Pointer parallax starts for desktop-capable pointers only.</li></ol><p>The foreground content is centered and readable at every breakpoint. The navigation is transparent at rest and gains a translucent blurred surface after the visitor scrolls. The CTA remains a visual <code>button</code> with no action until a product section is implemented.</p><h2 id="interaction-and-theme-behavior" tabindex="-1">Interaction and Theme Behavior <a class="header-anchor" href="#interaction-and-theme-behavior" aria-label="Permalink to “Interaction and Theme Behavior”">​</a></h2><ul><li>The scene layers respond to fine-pointer movement by at most 5px; the sunrise brightens by no more than 15% near the pointer.</li><li>Theme selection is stored in <code>localStorage</code> and defaults to the user&#39;s system color preference if no selection has been stored.</li><li>The theme switch animates the horizon from dark through copper-gold to ivory over 900-1200ms. It must not use a full-page flash.</li><li>In light mode, the background is <code>#F4F0E8</code>, the horizon becomes champagne and ivory, and orbit lines use subdued gold at low opacity.</li><li>On coarse pointers and small screens, pointer parallax is disabled, particles are reduced by half, and the intro is shortened.</li><li>With <code>prefers-reduced-motion: reduce</code>, all long-running motion, parallax, and smooth scrolling are disabled. The completed Hero fades in within 300ms.</li></ul><h2 id="design-tokens" tabindex="-1">Design Tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to “Design Tokens”">​</a></h2><p>Dark theme uses:</p><ul><li>Background <code>#080A0B</code></li><li>Elevated <code>#0E1112</code></li><li>Surface <code>#141718</code></li><li>Hover <code>#1B1E1F</code></li><li>Primary text <code>#F4F0E8</code></li><li>Secondary text <code>#A9A49A</code></li><li>Asumi gold <code>#C8A66A</code></li><li>Bright gold <code>#E2BD76</code></li><li>Deep gold <code>#84683D</code></li><li>Olive graphite <code>#51564F</code></li></ul><p>Light theme uses <code>#F4F0E8</code> as its background with ivory surfaces, <code>#171918</code> primary text, and the same copper-gold accent range at lower contrast.</p><p>Headings use a refined display serif, with a Persian-ready fallback; body copy uses a readable Persian sans-serif and Inter fallback. The implementation must not require a network font for first render.</p><h2 id="accessibility-and-performance" tabindex="-1">Accessibility and Performance <a class="header-anchor" href="#accessibility-and-performance" aria-label="Permalink to “Accessibility and Performance”">​</a></h2><ul><li>Respect <code>prefers-reduced-motion</code>, keyboard focus, semantic buttons, and a visible focus indicator.</li><li>Decorative scene SVGs are hidden from assistive technology; all meaningful text remains real HTML.</li><li>Use <code>transform</code> and <code>opacity</code> for animation where possible, pause ambient animation when the Hero is outside the viewport, and avoid layout thrashing.</li><li>Target 60 FPS on typical desktop hardware and 50-60 FPS on recent mobile devices without WebGL.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to “Validation”">​</a></h2><ul><li>Type-check and production-build the new Vite app.</li><li>Add focused component tests for theme persistence and reduced-motion behavior.</li><li>Verify root routing on <code>asumi.ir</code>, while <code>/desk</code>, <code>/dashboard</code>, and <code>/api</code> still resolve through Frappe.</li><li>Manually verify dark/light transition, mobile layout, keyboard focus, and reduced-motion behavior in a browser.</li></ul>',29)])])}const m=i(r,[["render",s]]);export{u as __pageData,m as default};
